// RECURSIVE DFS — O(V+E) time, O(V) space
function dfsRecursive(adj, start, visited = new Set()) {
    visited.add(start);           // mark before recursing
    console.log('Visit:', start);
    for (const neighbour of adj[start]) {
        if (!visited.has(neighbour)) {
            dfsRecursive(adj, neighbour, visited);
        }
    }
    return visited;
}

// ITERATIVE DFS — avoids call stack overflow for deep graphs
function dfsIterative(adj, start) {
    const visited = new Set();
    const stack = [start];
    while (stack.length) {
        const node = stack.pop();
        if (visited.has(node)) continue; // skip if already visited
        visited.add(node);
        console.log('Visit:', node);
        for (const neighbour of adj[node]) {
            if (!visited.has(neighbour)) stack.push(neighbour);
        }
    }
    return visited;
}

// COUNT CONNECTED COMPONENTS — O(V+E)
function countComponents(adj) {
    const V = adj.length;
    const visited = new Set();
    let components = 0;
    for (let v = 0; v < V; v++) {
        if (!visited.has(v)) {
            dfsRecursive(adj, v, visited); // explore entire component
            components++;                  // new component found
        }
    }
    return components;
}

// FIND ALL PATHS from src to dst
function findAllPaths(adj, src, dst) {
    const result = [];
    function dfs(node, path, visited) {
        if (node === dst) { result.push([...path]); return; }
        for (const nb of adj[node]) {
            if (!visited.has(nb)) {
                visited.add(nb);
                path.push(nb);
                dfs(nb, path, visited);
                path.pop();          // backtrack
                visited.delete(nb);  // backtrack
            }
        }
    }
    dfs(src, [src], new Set([src]));
    return result;
}

