// BFS with shortest path distances — O(V+E)
function bfs(adj, start) {
    const dist = new Array(adj.length).fill(-1);
    const parent = new Array(adj.length).fill(-1);
    const queue = [start];
    dist[start] = 0;

    while (queue.length) {
        const node = queue.shift(); // dequeue front (use proper O(1) queue in production)
        for (const nb of adj[node]) {
            if (dist[nb] === -1) {      // unvisited
                dist[nb] = dist[node] + 1;
                parent[nb] = node;
                queue.push(nb);
            }
        }
    }
    return { dist, parent };
}

// RECONSTRUCT SHORTEST PATH from src to dst
function shortestPath(adj, src, dst) {
    const { dist, parent } = bfs(adj, src);
    if (dist[dst] === -1) return null; // no path
    const path = [];
    for (let curr = dst; curr !== -1; curr = parent[curr]) {
        path.push(curr);
    }
    return path.reverse();
}

