// MULTI-SOURCE BFS: shortest distance from ANY of multiple sources
function multiBFS(adj, sources) {
    const dist = new Array(adj.length).fill(-1);
    const queue = [];
    for (const src of sources) {
        dist[src] = 0;
        queue.push(src);
    }
    while (queue.length) {
        const node = queue.shift();
        for (const nb of adj[node]) {
            if (dist[nb] === -1) {
                dist[nb] = dist[node] + 1;
                queue.push(nb);
            }
        }
    }
    return dist;
}
