// NUMBER OF ISLANDS — DFS flood fill, O(m*n)
function numIslands(grid) {
    const m = grid.length, n = grid[0].length;
    let count = 0;

    function floodFill(r, c) {
        // Boundary and water check
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] !== '1') return;
        grid[r][c] = '0';  // mark visited in-place: '1' -> '0'
        floodFill(r+1, c); // down
        floodFill(r-1, c); // up
        floodFill(r, c+1); // right
        floodFill(r, c-1); // left
    }

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === '1') {
                floodFill(r, c); // flood fill entire island
                count++;          // one complete island found
            }
        }
    }
    return count;
}

