// CLONE GRAPH — DFS with hash map: O(V+E)
function cloneGraph(node) {
    if (!node) return null;
    const cloneMap = new Map(); // original -> clone

    function dfs(curr) {
        if (cloneMap.has(curr)) return cloneMap.get(curr); // already cloned
        // Create clone for this node (no neighbours yet)
        const clone = new GraphNode(curr.val);
        cloneMap.set(curr, clone);    // register BEFORE recursing (handle cycles)
        // Clone all neighbours
        for (const nb of curr.neighbors) {
            clone.neighbors.push(dfs(nb)); // dfs returns clone of nb
        }
        return clone;
    }
    return dfs(node);
}

