// PACIFIC ATLANTIC WATER FLOW — reverse BFS O(m*n)
function pacificAtlantic(heights) {
    const m = heights.length, n = heights[0].length;
    const DIRS = [[1,0],[-1,0],[0,1],[0,-1]];

    function bfsFromBorder(starts) {
        const visited = new Set(starts.map(([r,c]) => r*n+c));
        const queue = [...starts];
        while (queue.length) {
            const [r, c] = queue.shift();
            for (const [dr, dc] of DIRS) {
                const nr = r+dr, nc = c+dc;
                const key = nr*n+nc;
                if (nr>=0&&nr<m&&nc>=0&&nc<n &&
                    !visited.has(key) &&
                    heights[nr][nc] >= heights[r][c]) { // uphill = reverse flow
                    visited.add(key);
                    queue.push([nr, nc]);
                }
            }
        }
        return visited;
    }

    // Pacific: top row + left column
    const pacificStarts = [];
    for (let r = 0; r < m; r++) pacificStarts.push([r, 0]);
    for (let c = 1; c < n; c++) pacificStarts.push([0, c]);

    // Atlantic: bottom row + right column
    const atlanticStarts = [];
    for (let r = 0; r < m; r++) atlanticStarts.push([r, n-1]);
    for (let c = 0; c < n-1; c++) atlanticStarts.push([m-1, c]);

    const pacific  = bfsFromBorder(pacificStarts);
    const atlantic = bfsFromBorder(atlanticStarts);

    // Intersection: cells in both visited sets
    const result = [];
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const key = r*n+c;
            if (pacific.has(key) && atlantic.has(key)) result.push([r, c]);
        }
    }
    return result;
}

