// SURROUNDED REGIONS — three-phase DFS: O(m*n)
function solve(board) {
    const m = board.length, n = board[0].length;

    // PHASE 1: DFS from all border 'O' cells, mark connected cells 'T'
    function dfs(r, c) {
        if (r<0||r>=m||c<0||c>=n||board[r][c]!=='O') return;
        board[r][c] = 'T'; // mark as safe (border-connected)
        dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
    }
    // Top and bottom borders
    for (let c = 0; c < n; c++) { dfs(0,c); dfs(m-1,c); }
    // Left and right borders
    for (let r = 0; r < m; r++) { dfs(r,0); dfs(r,n-1); }

    // PHASE 2: flip 'O' to 'X' (surrounded), restore 'T' to 'O' (safe)
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (board[r][c] === 'O') board[r][c] = 'X'; // surrounded: flip
            if (board[r][c] === 'T') board[r][c] = 'O'; // safe: restore
        }
    }
}

