// DETECT CYCLE IN DIRECTED GRAPH — three-colour DFS: O(V+E)
function hasCycleDirected(adj) {
    const V = adj.length;
    const color = new Array(V).fill(0); // 0=white, 1=grey, 2=black

    function dfs(u) {
        color[u] = 1; // grey: currently on stack
        for (const v of adj[u]) {
            if (color[v] === 1) return true;  // back edge: cycle!
            if (color[v] === 0 && dfs(v)) return true; // recurse unvisited
        }
        color[u] = 2; // black: fully processed
        return false;
    }

    for (let u = 0; u < V; u++) {
        if (color[u] === 0 && dfs(u)) return true;
    }
    return false;
}

// COURSE SCHEDULE (Blind 75 #207): can you finish all courses?
// numCourses=2, prerequisites=[[1,0]]: 0->1, no cycle -> true
// numCourses=2, prerequisites=[[1,0],[0,1]]: 0->1->0, cycle -> false
function canFinish(numCourses, prerequisites) {
    const adj = Array.from({length: numCourses}, () => []);
    for (const [course, prereq] of prerequisites) {
        adj[prereq].push(course); // prereq must be done before course
    }
    return !hasCycleDirected(adj);
}

console.log(canFinish(2, [[1,0]]));      // true
console.log(canFinish(2, [[1,0],[0,1]])); // false

// UNDIRECTED CYCLE DETECTION — parent tracking
function hasCycleUndirected(adj) {
    const visited = new Set();
    function dfs(u, parent) {
        visited.add(u);
        for (const v of adj[u]) {
            if (!visited.has(v)) {
                if (dfs(v, u)) return true;
            } else if (v !== parent) {
                return true; // visited and not parent: back edge = cycle
            }
        }
        return false;
    }
    for (let u = 0; u < adj.length; u++) {
        if (!visited.has(u) && dfs(u, -1)) return true;
    }
    return false;
}

