function classifyGraphPattern(signals) {
  const s = new Set(signals);
  if (s.has('grid')||s.has('islands')||s.has('cells')||s.has('flood_fill')) return 'Grid Flood Fill';
  if (s.has('connected_components')||s.has('path_exists')||s.has('clone')) return 'DFS Components';
  if (s.has('prerequisites')||s.has('cycle')||s.has('topological')||s.has('dependency')) return 'Directed Cycle/Topo';
  if (s.has('shortest_path')||s.has('minimum_steps')||s.has('fewest_edges')) return 'BFS Shortest Path';
  return 'Unknown';
}

function solveGridFloodFill(grid) {
  const m=grid.length,n=grid[0].length; let count=0;
  function ff(r,c){if(r<0||r>=m||c<0||c>=n||grid[r][c]!=='1')return;grid[r][c]='0';ff(r+1,c);ff(r-1,c);ff(r,c+1);ff(r,c-1);}
  for(let r=0;r<m;r++)for(let c=0;c<n;c++)if(grid[r][c]==='1'){ff(r,c);count++;}
  return count;
}

function solveDFSComponents(adj) {
  const visited=new Set(); let c=0;
  function dfs(u){visited.add(u);for(const v of adj[u])if(!visited.has(v))dfs(v);}
  for(let u=0;u<adj.length;u++)if(!visited.has(u)){dfs(u);c++;}
  return c;
}

function solveDirectedCycle(adj) {
  const color=new Array(adj.length).fill(0);
  function dfs(u){color[u]=1;for(const v of adj[u]){if(color[v]===1)return true;if(color[v]===0&&dfs(v))return true;}color[u]=2;return false;}
  for(let u=0;u<adj.length;u++)if(color[u]===0&&dfs(u))return true;
  return false;
}

function solveBFSShortestPath(adj, src, dst) {
  const dist=new Array(adj.length).fill(-1); const queue=[src]; dist[src]=0;
  while(queue.length){const node=queue.shift();for(const nb of adj[node])if(dist[nb]===-1){dist[nb]=dist[node]+1;queue.push(nb);}}
  return dist[dst];
}

function moduleCapabilitySummary() {
  const grid=[['1','0','1'],['0','0','0'],['1','0','1']];
  return {
    gridFloodFill: solveGridFloodFill(grid.map(r=>[...r])) === 4,
    dfsComponents: solveDFSComponents([[1],[0],[3],[2]]) === 2,
    directedCycle: solveDirectedCycle([[1],[2],[0]]) === true,
    bfsShortestPath: solveBFSShortestPath([[1,2],[0,3],[0,3],[1,2]], 0, 3) === 2
  };
}
